const ED = 'https://latex.giit.ch', ed = document.getElementById('ed');
addEventListener('message', e => {
  if (e.origin !== ED || e.source !== ed.contentWindow) return;
  const m = e.data;
  if (m.type === 'latexeditor:ready')
    ed.contentWindow.postMessage({ type: 'latexeditor:load', name: 'Offerte', content: meinText }, ED);
  if (m.type === 'latexeditor:change') alsUngespeichertMarkieren();
  if (m.type === 'latexeditor:save') aufDeinemServerSpeichern(m.content, m.assets);
});

ed.contentWindow.postMessage({ type: 'latexeditor:load', name: 'Offerte', content: meinText,
  ai: { label: 'Meine Verwaltung', prompt: 'Keep the placeholders.',
        endpoint: 'https://deine-seite.ch/api/ki-ergebnis', key: sitzungsSchluessel } }, ED);
